<?php
session_start();require_once '../shared/config.php';requireLogin('customer','login.php');$db=getDB();$customerId=(int)$_SESSION['customer_id'];$pincode=trim($_SESSION['customer_pincode']??'');$search=trim($_GET['search']??'');
$st=$db->prepare("SELECT i.*,v.store_name,v.pincode store_pincode,pm.mode,pm.price mode_price FROM items i JOIN vendors v ON v.id=i.vendor_id LEFT JOIN product_modes pm ON pm.item_id=i.id AND pm.available=1 WHERE i.available=1 AND (NOT EXISTS(SELECT 1 FROM product_modes x WHERE x.item_id=i.id) OR pm.id IS NOT NULL) AND (i.id IN (SELECT item_id FROM user_events WHERE customer_id=? AND item_id IS NOT NULL) OR i.category IN (SELECT i2.category FROM user_events e JOIN items i2 ON i2.id=e.item_id WHERE e.customer_id=? AND i2.category IS NOT NULL) OR v.pincode LIKE ? OR i.name LIKE ?) GROUP BY i.id ORDER BY (CASE WHEN v.pincode LIKE ? THEN 0 ELSE 1 END),i.created_at DESC LIMIT 12");
$likePin=substr($pincode,0,3).'%';$likeSearch=$search?'%'.$search.'%':'%';$st->execute([$customerId,$customerId,$likePin,$likeSearch,$likePin]);$items=$st->fetchAll();
$reason=$pincode?'your area and available catalogue':'your activity and available catalogue';
?><!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Smart Recommendations – O2O Tradition</title><style>
body{font-family:Arial;background:#FAF6EE;color:#3D2B0F;margin:0}.nav{background:#1A1108;color:#C9A84C;padding:18px 28px}.nav a{color:#E8CC82;text-decoration:none;margin-left:18px}.main{max-width:1100px;margin:auto;padding:30px}.hero,.card{background:#fff;border:1px solid #E8E0D0;padding:22px;margin-bottom:20px}.hero{background:#21170B;color:#fff}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:18px}.item{background:#fff;border:1px solid #E8E0D0;text-decoration:none;color:inherit}.pic{height:180px;background:#E8E0D0;display:flex;align-items:center;justify-content:center;font-size:55px}.pic img{width:100%;height:180px;object-fit:cover}.body{padding:14px}.name{font:22px Georgia,serif}.store{font-size:11px;color:#C9A84C;margin:5px 0}.meta{font-size:13px;color:#8B1A1A;font-weight:bold}.small{font-size:12px;color:#777;line-height:1.6}</style></head><body><div class="nav"><b>O2O Tradition</b><a href="home.php">← Explore</a><a href="stylist.php">AI Stylist</a></div><main class="main"><section class="hero"><h1>✦ Smart Recommendations</h1><p>Items are surfaced from signals available in your account, including previous item activity and hyperlocal catalogue availability. <?=htmlspecialchars($reason)?>.</p></section><section class="card"><h2>Recommended for you</h2><p class="small">This first version uses transparent catalogue signals rather than inventing preferences or claiming that an item is guaranteed to suit you.</p></section><?php if(!$items):?><section class="card"><h2>No recommendations yet</h2><p class="small">Browse or search a few items and O2O Tradition will have more activity signals to work with.</p></section><?php else:?><div class="grid"><?php foreach($items as $item):?><a class="item" href="item.php?id=<?=$item['id']?>"><div class="pic"><?php if($item['image_path']&&file_exists('../uploads/items/'.$item['image_path'])):?><img src="../uploads/items/<?=htmlspecialchars($item['image_path'])?>" alt="<?=htmlspecialchars($item['name'])?>"><?php else:?>👘<?php endif;?></div><div class="body"><div class="name"><?=htmlspecialchars($item['name'])?></div><div class="store"><?=htmlspecialchars($item['store_name'])?></div><div class="meta"><?=htmlspecialchars(ucfirst($item['mode']??'rent'))?> · ₹<?=number_format((float)($item['mode_price']??$item['rent_per_day']),0)?></div><div class="small"><?=htmlspecialchars($item['category']??'Traditional wear')?></div></div></a><?php endforeach;?></div><?php endif;?></main></body></html>